// Terjemahkan strategi aktif → kuota harian + konteks prompt. Fallback ke env kalau kosong.
const changes = ($json.changes && typeof $json.changes === 'object') ? $json.changes : {};
const quota = changes.quota || {};
const quotaId = Number(quota.id || $env.POSTS_PER_DAY_ID || 3);
const quotaEn = Number(quota.en || $env.POSTS_PER_DAY_EN || 2);
const strategy = {
  hook_style: String(changes.hook_style || ''),
  tone: String(changes.tone || ''),
  keywords: Array.isArray(changes.keywords_id) ? changes.keywords_id : [],
  min_score: Number(changes.min_score || 0) || Number($env.AI_GATE_MIN || 70)
};
return { json: { quotaId, quotaEn, strategy } };

// Konfigurasi per track + prompt naskah video.
const p = $('Product Found?').item.json;
const trendKw = ($json.trends || []).map(t => t.keyword).filter(Boolean);
const isEN = p.track === 'en';
const lang = isEN ? 'en' : 'id';
const voice = isEN ? 'en-US-JennyNeural' : 'id-ID-GadisNeural';
const handle = isEN ? ($env.HANDLE_EN || '@yourchannel') : ($env.HANDLE_ID || '@primefinds.id');
const strat = $('Prepare Pick').item.json.strategy || {};

const toneEN = 'Casual American TikTok voice, punchy, no cringe, honest-review energy.';
const toneID = 'Bahasa Indonesia santai ala TikTok, gen Z, to the point, tidak norak.';
const priceTxt = p.price_min ? `Harga sekitar Rp${Math.round(Number(p.price_min))}` : '';

const systemPrompt = isEN
  ? 'You are a short-form video scriptwriter for a faceless affiliate channel reviewing software/AI tools and gadgets. Output STRICT JSON only.'
  : 'Kamu penulis naskah video pendek untuk akun finds/affiliation Indonesia. Output HANYA JSON ketat.';

const userPrompt = `Produk: ${p.title}
Toko/sumber: ${p.shop_name || '-'}
${priceTxt}
Komisi: ${p.commission_rate ? (Number(p.commission_rate) * 100).toFixed(1) + '%' : (p.commission_amt || '-')}

Buat naskah video 3-4 scene (total narasi 20-35 detik):
- Scene 1 = HOOK 1 kalimat yang bikin stop scroll (tanpa bohong, tanpa klaim berlebihan)
- Scene 2-3 = benefit nyata + bukti dari data produk (jangan mengarang fitur)
- Scene terakhir = CTA (klik keranjang kuning / link di bio)
Gaya: ${isEN ? toneEN : toneID}${strat.hook_style ? `
Gaya hook (hasil analis): ${strat.hook_style}` : ''}${strat.tone ? `
Nada (hasil analis): ${strat.tone}` : ''}

${trendKw.length ? `\nTrend pasar saat ini (pakai untuk hook/hashtag HANYA bila relevan, jangan dipaksakan): ${trendKw.slice(0, 5).join(', ')}` : ''}
Format JSON:
{
  "title": "judul internal singkat",
  "hook": "kalimat hook",
  "scenes": [{"text":"..."},{"text":"..."},{"text":"..."}],
  "caption": "caption postingan 1-2 kalimat",
  "hashtags": "#tag1 #tag2 #tag3 (3-5 tag relevan, boleh 1-2 dari trend pasar bila cocok)"
}
Aturan: maksimal 20 kata per scene. Tanpa emoji di dalam scene text (jadi subtitle).`;

const payload = {
  model: $env.LLM_MODEL,
  temperature: 0.8,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return {
  json: {
    ...p,
    lang,
    voice,
    handle,
    gate_min: strat.min_score || Number($env.AI_GATE_MIN || 70),
    scriptRequest: payload,
    scriptEndpoint: ($env.LLM_BASE_URL || '').replace(/\/$/, '') + '/chat/completions',
    scriptAuth: 'Bearer ' + ($env.LLM_API_KEY || '')
  }
};

// Parse JSON naskah dari LLM (toleran terhadap code fence).
const ctx = $('Track Config + Script Prompt').item.json;
let content = $json.choices[0].message.content || '';
content = content.replace(/^```(json)?\s*/i, '').replace(/```\s*$/, '').trim();
const m = content.match(/\{[\s\S]*\}/);
if (!m) throw new Error('LLM tidak menghasilkan JSON: ' + content.slice(0, 300));
const s = JSON.parse(m[0]);

const scenes = [];
const hookText = (s.hook || (s.scenes && s.scenes[0] && s.scenes[0].text) || '').trim();
if (hookText) scenes.push({ text: hookText, image: ctx.image_url, style: 'hook' });
for (const sc of (s.scenes || [])) {
  const t = (sc.text || '').trim();
  if (!t || t === hookText) continue;
  scenes.push({ text: t, image: ctx.image_url });
}
if (scenes.length < 2) throw new Error('naskah kurang dari 2 scene');

const caption = ((s.caption || '') + ' ' + (s.hashtags || '')).trim().slice(0, 900);
const gatePrompt = `Kamu manajer kualitas konten. nilai video singkat ini.
Produk: ${ctx.title}
Naskah: ${JSON.stringify(scenes.map(x => x.text))}
Caption: ${caption}

Rubrik (0-100):
- Hook 3 detik pertama (30)
- Jujur & tidak mengarang fitur (30)
- Kepatuhan platform: tanpa klaim medis/kemenangan pasti/tanpa spam (25)
- Keterbacaan subtitle (15)

Output JSON: {"score": 0-100, "compliant": true/false, "reasons": ["..."]}`;

return {
  json: {
    ...ctx,
    title_script: s.title || ctx.title,
    hook: hookText,
    scenes,
    caption,
    gateRequest: {
      model: ctx.scriptRequest.model,
      temperature: 0.2,
      messages: [
        { role: 'system', content: 'You are a strict content QA manager. JSON output only.' },
        { role: 'user', content: gatePrompt }
      ]
    }
  }
};

// Evaluasi gate: output 0 = LULUS (lanjut render), output 1 = TOLAK.
const ctx = $('Parse Script').item.json;
let content = $json.choices[0].message.content || '';
content = content.replace(/^```(json)?\s*/i, '').replace(/```\s*$/, '').trim();
const m = content.match(/\{[\s\S]*\}/);
const verdict = m ? JSON.parse(m[0]) : { score: 0, compliant: false, reasons: ['gate parse error'] };

const min = Number(ctx.gate_min || $env.AI_GATE_MIN || 70);
const pass = Number(verdict.score) >= min && verdict.compliant === true;

const item = {
  json: {
    ...ctx,
    ai_score: Number(verdict.score) || 0,
    ai_verdict: verdict,
    gate_min: min,
    gate_pass: pass
  }
};
// Code node n8n = satu output -> WAJIB array of items (flat).
return [item];

